JEUX = [
 ("perifrasisExercises", "Perífrasis", PERIFRASIS, "perifrasis", "startPerifrasisUebung",
  "(ir a · estar + gérondif · acabar de · volver a · seguir · tener que · hay que · dejar de · empezar a)",
  "(ir a · estar + gerund · acabar de · volver a · seguir · tener que · hay que · dejar de · empezar a)"),
 ("numerosExercises", "Números y hora", NUMEROS, "numeros-hora", "startNumerosUebung",
  "(16-29 en un mot · y à partir de 31 · cien / ciento · centaines accordées · es la una, son las…)",
  "(16-29 as one word · y from 31 · cien / ciento · hundreds agree · es la una, son las...)"),
 ("demostrativosExercises", "Demostrativos y posesivos", DEMOSTRATIVOS, "demostrativos-posesivos", "startDemostrativosUebung",
  "(este : près de moi · ese : près de toi · aquel : loin · esto, eso : neutres · mi devant le nom, mío après)",
  "(este: near me · ese: near you · aquel: far · esto, eso: neuter · mi before the noun, mío after)"),
 ("preposicionesExercises", "Preposiciones", PREPOSICIONES, "preposiciones", "startPreposicionesUebung",
  "(a : mouvement, heure, personne · en : lieu, transport, date · de : origine, matière, possession)",
  "(a: movement, time, person · en: place, transport, date · de: origin, material, possession)"),
]


def main():
    chemin = os.path.join(DATOS, "ejercicios.json")
    d = json.load(io.open(chemin, encoding="utf-8"))
    g = os.path.join(DATOS, "grammaire.json")
    gd = json.load(io.open(g, encoding="utf-8"))
    fiches = {f["id"]: f for f in gd["fiches"]}
    for cle, sujet, lignes, fiche, fonction, ind, ind_en in JEUX:
        questions = [l[0] for l in lignes]
        assert len(set(questions)) == len(questions), cle
        out = []
        for q, bonne, options, fr, en, xfr, xen in lignes:
            assert q.count("___") == 1, q
            assert bonne in options and len(set(options)) == len(options) == 3, q
            out.append({"topic": sujet, "question": q, "question_en": q,
                        "translation": fr, "translation_en": en, "hint": ind, "hint_en": ind_en,
                        "answers": [bonne], "correct": bonne, "correctEn": bonne,
                        "explanation": xfr, "explanation_en": xen,
                        "options": options, "optionsEn": options})
        d["jeux"][cle] = out
        fiches[fiche]["exercice"] = fonction
        print("%-24s %2d questions -> fiche %s" % (cle, len(out), fiche))
    io.open(chemin, "w", encoding="utf-8").write(json.dumps(d, ensure_ascii=False, indent=1) + "\n")
    io.open(g, "w", encoding="utf-8", newline="\n").write(json.dumps(gd, ensure_ascii=False, indent=1) + "\n")


if __name__ == "__main__":
    main()
